<?php
require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_admin();
$reports=$pdo->query("SELECT r.*,u.name citizen,t.team_name FROM reports r JOIN users u ON u.id=r.user_id LEFT JOIN teams t ON t.id=r.assigned_team_id ORDER BY FIELD(r.severity,'Critical','Moderate','Low'),r.created_at DESC")->fetchAll();
$teams=$pdo->query("SELECT * FROM teams ORDER BY team_name")->fetchAll();
$pageTitle='Manage reports';require __DIR__.'/../includes/header.php';
?>
<section class="page-heading"><div><span class="eyebrow">FIELD OPERATIONS</span><h1>Manage reports</h1><p class="muted">Assign maintenance teams and update repair statuses.</p></div><a class="btn btn-light" href="dashboard.php">← Admin overview</a></section>
<div class="admin-report-list"><?php if(!$reports):?><div class="empty-state">There are no reports to manage yet.</div><?php endif;?><?php foreach($reports as $r):?><article class="manage-card"><div class="manage-card-top"><div><div class="card-tags"><span class="severity severity-<?=strtolower($r['severity'])?>"><?=e($r['severity'])?></span><span class="status status-<?=status_class($r['status'])?>"><?=e($r['status'])?></span></div><h3><?=e($r['title'])?></h3><p class="location-line">📍 <?=e($r['location'])?></p></div><?php if($r['photo']):?><a href="../uploads/<?=e($r['photo'])?>" target="_blank"><img class="manage-photo" src="../uploads/<?=e($r['photo'])?>" alt="Damage photo"></a><?php endif;?></div><p><?=e($r['description'])?></p><div class="manage-meta">Submitted by <?=e($r['citizen'])?> · <?=date('d M Y, h:i A',strtotime($r['created_at']))?></div><div class="manage-actions"><form method="post" action="assign_team.php" class="inline-form"><input type="hidden" name="report_id" value="<?=$r['id']?>"><label>Maintenance team<select name="team_id"><option value="">Unassigned</option><?php foreach($teams as $t):?><option value="<?=$t['id']?>" <?=((int)$r['assigned_team_id']===(int)$t['id'])?'selected':''?>><?=e($t['team_name'])?></option><?php endforeach;?></select></label><button class="btn btn-dark btn-small">Save team</button></form><form method="post" action="update_status.php" class="inline-form"><input type="hidden" name="report_id" value="<?=$r['id']?>"><label>Repair status<select name="status"><?php foreach(['Reported','Under Repair','Resolved'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><button class="btn btn-primary btn-small">Update status</button></form></div></article><?php endforeach;?></div>
